  select * from jsonb_to_recordset($q$[{"topic":"Number","subtopic":"Fractions, decimals and percentages","spec_ref":"M1.1","command_word":"calculate","difficulty":"foundation","total_marks":2,"question_text":"Work out 2¾ ÷ 1⅚\n\nGive your answer as a mixed number in its simplest form. Show your working.","marking_style":"points","scheme":{"max":2,"points":["Converts to improper fractions and multiplies by the reciprocal: 11/4 × 6/11","1½"],"guidance":"Accept 3/2 for the method mark only; the answer mark needs the mixed number 1½. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":1},{"topic":"Number","subtopic":"Indices and standard form","spec_ref":"M1.2","command_word":"calculate","difficulty":"foundation","total_marks":2,"question_text":"Work out (6 × 10⁵) × (4 × 10⁻²)\n\nGive your answer in standard form.","marking_style":"points","scheme":{"max":2,"points":["24 × 10³ or 24 000 seen","2.4 × 10⁴"],"guidance":"24 × 10³ (not in standard form) scores 1."},"ao_marks":{"AO1":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":2},{"topic":"Ratio, Proportion and Rates of Change","subtopic":"Compound measures","spec_ref":"M4.3","command_word":"calculate","difficulty":"foundation","total_marks":3,"question_text":"A train travels 150 km in 1 hour 15 minutes.\n\nWork out the average speed of the train in km/h. Show your working.","marking_style":"points","scheme":{"max":3,"points":["Converts the time: 1 hour 15 minutes = 1.25 hours (or 75 minutes)","Uses speed = distance ÷ time: 150 ÷ 1.25 (or 150 ÷ 75 × 60)","120 km/h"],"guidance":"Using 1.15 hours loses the first mark but can score the method mark. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":1},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":3},{"topic":"Ratio, Proportion and Rates of Change","subtopic":"Ratio","spec_ref":"M4.1","command_word":"determine","difficulty":"foundation","total_marks":3,"question_text":"Amir and Beth share some sweets in the ratio 3 : 5.\n\nBeth gets 24 more sweets than Amir.\n\nHow many sweets are there altogether? Show your working.","marking_style":"points","scheme":{"max":3,"points":["The difference is 5 − 3 = 2 parts","1 part = 24 ÷ 2 = 12","Total = 8 × 12 = 96"],"guidance":"Treating 24 as the total or as Beth's share scores 0. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":1,"AO3":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":4},{"topic":"Algebra: Expressions and Equations","subtopic":"Expanding and factorising","spec_ref":"M2.1","command_word":"determine","difficulty":"foundation","total_marks":4,"question_text":"(a) Expand and simplify (x + 5)(x − 3)\n\n(b) Factorise fully 6x²y − 9xy²","marking_style":"points","scheme":{"max":4,"points":["(a) At least three of the four terms correct: x², −3x, +5x, −15","(a) x² + 2x − 15","(b) Takes out a correct common factor, e.g. 3x(2xy − 3y²) or xy(6x − 9y)","(b) 3xy(2x − 3y)"],"guidance":"In (b) the final mark needs the fully factorised form."},"ao_marks":{"AO1":4},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":5},{"topic":"Geometry: Shapes, Angles and Measures","subtopic":"Angles and polygons","spec_ref":"M5.1","command_word":"calculate","difficulty":"foundation","total_marks":3,"question_text":"Each interior angle of a regular polygon is 156°.\n\nWork out the number of sides the polygon has. Show your working.","marking_style":"points","scheme":{"max":3,"points":["Exterior angle = 180° − 156° = 24°","Number of sides = 360 ÷ 24","15 sides"],"guidance":"The algebraic method (n − 2) × 180 = 156n, giving 24n = 360, can score full marks. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":1},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":6},{"topic":"Algebra: Expressions and Equations","subtopic":"Linear and quadratic equations","spec_ref":"M2.2","command_word":"determine","difficulty":"foundation","total_marks":3,"question_text":"Solve (3x − 1)/4 = x − 2\n\nShow your working.","marking_style":"points","scheme":{"max":3,"points":["Multiplies both sides by 4: 3x − 1 = 4(x − 2)","Expands and collects terms, e.g. 3x − 1 = 4x − 8","x = 7"],"guidance":"3x − 1 = 4x − 2 (not multiplying both terms by 4) loses the first mark; allow follow-through for the second. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":7},{"topic":"Number","subtopic":"Bounds, rounding and estimation","spec_ref":"M1.4","command_word":"calculate","difficulty":"foundation","total_marks":3,"question_text":"Work out an estimate for\n\n(4.87 × 61.2) ÷ 0.198\n\nShow your working.","marking_style":"points","scheme":{"max":3,"points":["Rounds each number to 1 significant figure: 5, 60 and 0.2","5 × 60 = 300, then 300 ÷ 0.2","1500"],"guidance":"Accept 1470 from 4.9 × 60 ÷ 0.2 if the rounding is shown. An exact answer (about 1505) with no rounding shown is not an estimate and scores 0. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":8},{"topic":"Ratio, Proportion and Rates of Change","subtopic":"Direct and inverse proportion","spec_ref":"M4.2","command_word":"determine","difficulty":"foundation","total_marks":3,"question_text":"It takes 6 builders 10 days to build a wall. All the builders work at the same rate.\n\n(a) How many days would it take 4 builders to build the same wall?\n\n(b) The wall must be built in 5 days. How many builders are needed?\n\nShow your working.","marking_style":"points","scheme":{"max":3,"points":["Total work = 6 × 10 = 60 builder-days","(a) 60 ÷ 4 = 15 days","(b) 60 ÷ 5 = 12 builders"],"guidance":"Treating it as direct proportion (e.g. 6.7 days for 4 builders) scores 0 for that part. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":1,"AO2":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":9},{"topic":"Ratio, Proportion and Rates of Change","subtopic":"Percentage change, growth and decay","spec_ref":"M4.4","command_word":"calculate","difficulty":"foundation","total_marks":3,"question_text":"Sophie invests £2000 for 2 years at 5% per year compound interest.\n\nWork out the value of her investment at the end of 2 years. Show your working.","marking_style":"points","scheme":{"max":3,"points":["After 1 year: 2000 + 100 = £2100 (or 2000 × 1.05)","After 2 years: 2100 + 105 (or 2100 × 1.05)","£2205"],"guidance":"Simple interest (£2200) scores 1 for the first year only. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO2":1},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":10},{"topic":"Probability","subtopic":"Venn diagrams and set notation","spec_ref":"M7.3","command_word":"calculate","difficulty":"higher","total_marks":4,"question_text":"There are 30 students in a class.\n18 study French.\n14 study Spanish.\n5 study neither French nor Spanish.\n\nA student is chosen at random. Work out the probability that the student studies both French and Spanish.\n\nYou may describe a Venn diagram in words. Show your working.","marking_style":"points","scheme":{"max":4,"points":["30 − 5 = 25 students study at least one of the languages","18 + 14 − 25 = 7 study both","Correct Venn regions: French only 11, both 7, Spanish only 7, neither 5","7/30"],"guidance":"Max 4. 7 (a number, not a probability) as the final answer loses the last mark. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":11},{"topic":"Algebra: Graphs, Sequences and Functions","subtopic":"Straight-line graphs","spec_ref":"M3.1","command_word":"determine","difficulty":"higher","total_marks":3,"question_text":"A straight line passes through the points (1, 4) and (5, 12).\n\nFind an equation of the line. Show your working.","marking_style":"points","scheme":{"max":3,"points":["Gradient = (12 − 4) ÷ (5 − 1) = 2","Substitutes a point: 4 = 2 × 1 + c, so c = 2","y = 2x + 2 (or an equivalent equation)"],"guidance":"Allow error carried forward from a wrong gradient for the substitution mark. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":12},{"topic":"Geometry: Trigonometry, Vectors and Transformations","subtopic":"Pythagoras and right-angled trigonometry","spec_ref":"M6.1","command_word":"calculate","difficulty":"higher","total_marks":3,"question_text":"A ladder 6.5 m long leans against a vertical wall. The foot of the ladder is on horizontal ground, 2.5 m from the bottom of the wall.\n\nHow far up the wall does the ladder reach? Show your working.","marking_style":"points","scheme":{"max":3,"points":["Uses Pythagoras with the ladder as the hypotenuse: h² = 6.5² − 2.5²","= 42.25 − 6.25 = 36","h = 6 m"],"guidance":"Adding the squares (6.5² + 2.5²) scores 0. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":1},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":13},{"topic":"Algebra: Expressions and Equations","subtopic":"Simultaneous equations","spec_ref":"M2.3","command_word":"determine","difficulty":"higher","total_marks":4,"question_text":"Solve the simultaneous equations\n\n3x + 2y = 4\n5x − 3y = 13\n\nShow your working.","marking_style":"points","scheme":{"max":4,"points":["Makes the coefficients of one variable the same size, e.g. 9x + 6y = 12 and 10x − 6y = 26","Adds or subtracts correctly to eliminate a variable, e.g. 19x = 38","x = 2","y = −1"],"guidance":"Substitution is an acceptable method. Trial and improvement with no algebra scores at most 1 mark. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":4},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":14},{"topic":"Geometry: Shapes, Angles and Measures","subtopic":"Area, volume and surface area","spec_ref":"M5.2","command_word":"calculate","difficulty":"higher","total_marks":4,"question_text":"A solid cylinder has radius 3 cm and height 10 cm.\n\n(a) Work out the volume of the cylinder.\n(b) Work out the total surface area of the cylinder.\n\nGive both answers in terms of π. Show your working.","marking_style":"points","scheme":{"max":4,"points":["(a) Volume = π × 3² × 10","(a) 90π cm³","(b) Two circular ends = 2 × π × 3² = 18π and curved surface = 2 × π × 3 × 10 = 60π","(b) 78π cm²"],"guidance":"Answers given as decimals (e.g. 282.7) instead of in terms of π lose the answer mark for that part. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":4},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":15},{"topic":"Number","subtopic":"Fractions, decimals and percentages","spec_ref":"M1.1","command_word":"justify","difficulty":"higher","total_marks":3,"question_text":"The recurring decimal 0.454545... (0.4̇5̇) can be written as a fraction.\n\nUse algebra to show that 0.454545... = 5/11","marking_style":"points","scheme":{"max":3,"points":["Lets x = 0.4545... and writes 100x = 45.4545...","Subtracts to get 99x = 45","x = 45/99 = 5/11"],"guidance":"This is a 'show that' question: every step must be written down. Dividing 5 by 11 to get 0.4545... does not use algebra and scores 0."},"ao_marks":{"AO2":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":16},{"topic":"Number","subtopic":"Indices and standard form","spec_ref":"M1.2","command_word":"calculate","difficulty":"higher","total_marks":3,"question_text":"(a) Work out the value of 27^(−2/3)\n\n(b) Work out the value of 81^(3/4)","marking_style":"points","scheme":{"max":3,"points":["(a) Uses the cube root: 27^(1/3) = 3 (or 27^(2/3) = 9)","(a) 1/9","(b) 27"],"guidance":"In (a), 9 or −9 scores the first mark only."},"ao_marks":{"AO1":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":17},{"topic":"Algebra: Expressions and Equations","subtopic":"Inequalities and rearranging formulae","spec_ref":"M2.4","command_word":"determine","difficulty":"higher","total_marks":3,"question_text":"Make x the subject of the formula\n\ny = (2x + 3)/(x − 1)\n\nShow your working.","marking_style":"points","scheme":{"max":3,"points":["Multiplies both sides by (x − 1): y(x − 1) = 2x + 3","Collects the x terms on one side: xy − 2x = y + 3","Factorises and divides: x = (y + 3)/(y − 2)"],"guidance":"Accept equivalent forms, e.g. x = (−y − 3)/(2 − y). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":18},{"topic":"Algebra: Graphs, Sequences and Functions","subtopic":"Quadratic and other graphs","spec_ref":"M3.2","command_word":"explain","difficulty":"higher","total_marks":4,"question_text":"(a) Write x² − 6x + 11 in the form (x − a)² + b, where a and b are integers.\n\n(b) Hence write down the coordinates of the turning point of the graph of y = x² − 6x + 11.\n\n(c) Explain how your answer to (a) shows that the equation x² − 6x + 11 = 0 has no real solutions.","marking_style":"points","scheme":{"max":4,"points":["(a) (x − 3)² seen","(a) (x − 3)² + 2","(b) (3, 2)","(c) (x − 3)² is never negative, so x² − 6x + 11 is always at least 2 and can never equal 0 (or: the minimum point is above the x-axis)"],"guidance":"Allow error carried forward from (a) into (b)."},"ao_marks":{"AO1":2,"AO2":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":19},{"topic":"Algebra: Graphs, Sequences and Functions","subtopic":"Functions and iteration","spec_ref":"M3.4","command_word":"determine","difficulty":"higher","total_marks":4,"question_text":"f(x) = 2x − 1 and g(x) = x²\n\n(a) Find fg(3).\n(b) Find f⁻¹(x).\n(c) Solve gf(x) = 25","marking_style":"points","scheme":{"max":4,"points":["(a) fg(3) = f(9) = 17","(b) f⁻¹(x) = (x + 1)/2","(c) gf(x) = (2x − 1)², so 2x − 1 = 5 or 2x − 1 = −5","(c) x = 3 or x = −2"],"guidance":"In (a), working out gf(3) = 25 (the wrong order) scores 0. In (c), both solutions are needed for the last mark."},"ao_marks":{"AO1":3,"AO2":1},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":20},{"topic":"Statistics","subtopic":"Histograms","spec_ref":"M8.3","command_word":"calculate","difficulty":"higher","total_marks":4,"question_text":"The table shows how long 38 people waited at a clinic, t minutes.\n\n0 < t ≤ 10: 8 people\n10 < t ≤ 15: 12 people\n15 < t ≤ 30: 18 people\n\n(a) A histogram is to be drawn for this data. Work out the frequency density for each class.\n\n(b) Estimate the number of people who waited between 12 and 20 minutes.\n\nShow your working.","marking_style":"points","scheme":{"max":4,"points":["(a) Uses frequency density = frequency ÷ class width","(a) 0.8, 2.4 and 1.2","(b) 12 to 15 minutes: 3/5 × 12 = 7.2; 15 to 20 minutes: 5/15 × 18 = 6","(b) 13.2, so about 13 people"],"guidance":"Accept 13 or 13.2 for the final mark. Allow error carried forward from wrong frequency densities in (b). This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":21},{"topic":"Geometry: Shapes, Angles and Measures","subtopic":"Congruence and similarity","spec_ref":"M5.4","command_word":"calculate","difficulty":"higher","total_marks":4,"question_text":"Two solid cones are mathematically similar.\n\nThe surface area of the smaller cone is 20 cm².\nThe surface area of the larger cone is 45 cm².\nThe volume of the smaller cone is 16 cm³.\n\nWork out the volume of the larger cone. Show your working.","marking_style":"points","scheme":{"max":4,"points":["Area scale factor = 45 ÷ 20 = 9/4","Length scale factor = 3/2","Volume scale factor = (3/2)³ = 27/8","16 × 27/8 = 54 cm³"],"guidance":"Using the area scale factor for the volume (16 × 9/4 = 36) scores 1. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":2},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":22},{"topic":"Geometry: Trigonometry, Vectors and Transformations","subtopic":"Vectors","spec_ref":"M6.3","command_word":"determine","difficulty":"higher","total_marks":3,"question_text":"OAB is a triangle. The vector from O to A is a and the vector from O to B is b.\n\nM is the midpoint of AB.\nN is the point on OB such that ON = ⅔ OB.\n\nFind the vector MN in terms of a and b. Give your answer in its simplest form. Show your working.","marking_style":"points","scheme":{"max":3,"points":["AB = b − a","OM = a + ½(b − a) = ½a + ½b","MN = ON − OM = ⅔b − ½a − ½b = −½a + ⅙b"],"guidance":"Accept ⅙b − ½a or (b − 3a)/6. This question asks for working. A correct final answer with no working scores only the mark(s) for the answer itself, not the method marks. Award each method mark when that step is shown. If the working has a slip (e.g. a wrong number copied) but the final answer is correct, withhold only the mark(s) for the step that is wrong."},"ao_marks":{"AO1":2,"AO3":1},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":23},{"topic":"Probability","subtopic":"Tree diagrams and conditional probability","spec_ref":"M7.2","command_word":"justify","difficulty":"higher","total_marks":5,"question_text":"There are n sweets in a bag. 6 of the sweets are orange.\n\nSam takes a sweet at random and eats it. He then takes another sweet at random and eats it.\n\nThe probability that Sam eats two orange sweets is 1/3.\n\n(a) Show that n² − n − 90 = 0\n\n(b) Work out the number of sweets that were in the bag at the start.","marking_style":"points","scheme":{"max":5,"points":["(a) P(first orange) = 6/n and P(second orange) = 5/(n − 1)","(a) 6/n × 5/(n − 1) = 1/3","(a) Rearranges: 90 = n(n − 1), so n² − n − 90 = 0","(b) Factorises: (n − 10)(n + 9) = 0","(b) n = 10, rejecting n = −9 because the number of sweets can't be negative"],"guidance":"(a) is a 'show that': the given equation must follow from the working. Using 6/n for both picks (with replacement) scores 0 for (a), but (b) can still score in full."},"ao_marks":{"AO2":2,"AO3":3},"spag_marks":0,"paper_ref":"edexcel-1ma1-h-p1-mock1","paper_number":24}]$q$::jsonb) as x(topic text, subtopic text, spec_ref text, command_word text, difficulty text, total_marks int, question_text text, marking_style text, scheme jsonb, ao_marks jsonb, spag_marks int, paper_ref text, paper_number int)
),
ins as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active, paper_ref, paper_number)
  select st.id, t.id, src.question_text, src.command_word, src.total_marks, src.difficulty, 'Pearson Edexcel', src.spec_ref, true, src.paper_ref, src.paper_number
  from src
  join public.subjects s on s.name = 'Maths'
  join public.topics t on t.subject_id = s.id and t.name = src.topic
  join public.subtopics st on st.topic_id = t.id and st.name = src.subtopic
  where not exists (select 1 from public.fm_exam_questions e where e.question_text = src.question_text)
  returning id, question_text
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select ins.id, src.marking_style, src.scheme, src.ao_marks, src.spag_marks from ins join src using (question_text);

commit;
